/* Hidden attribute safeguard */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #1c2024;
  --color-panel: #2d333b;
  --color-border-dark: #121517;
  --color-border-light: #525c68;
  --color-accent-gold: #f5a623;
  --color-accent-soft: #ffe082;
  --color-white: #f0f6fc;
  --color-text-dim: #adbac7;
  --color-accent-done: #56d364;
  --pixel-shadow: 
    4px 0 0 0 var(--color-border-dark),
    -4px 0 0 0 var(--color-border-dark),
    0 4px 0 0 var(--color-border-dark),
    0 -4px 0 0 var(--color-border-dark);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--color-bg);
  color: var(--color-white);
  font-family: "Courier New", Courier, monospace, monospace;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 1rem;
  image-rendering: pixelated;
}

.container {
  width: 100%;
  max-width: 440px;
  min-width: 320px;
  margin: 0 auto;
}

.pixel-card {
  background-color: var(--color-panel);
  box-shadow: var(--pixel-shadow);
  border: 4px solid var(--color-border-light);
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

.card-header {
  text-align: center;
}

.pixel-title {
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--color-accent-gold);
  text-shadow: 2px 2px 0 var(--color-border-dark);
  margin-bottom: 6px;
}

.pixel-subtitle {
  font-size: 1rem;
  color: var(--color-text-dim);
  letter-spacing: 1px;
}

/* Pixel Art Egg Container */
.pixel-egg-graphic {
  width: 100px;
  height: 110px;
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
}

.egg-shape {
  width: 76px;
  height: 96px;
  background: #f7fafc;
  border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;
  border: 4px solid var(--color-border-dark);
  position: relative;
  overflow: hidden;
  box-shadow: inset -4px -6px 0 rgba(0, 0, 0, 0.15);
}

.egg-yolk {
  position: absolute;
  bottom: 12px;
  left: 50%;
  transform: translateX(-50%);
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: var(--color-accent-gold);
  border: 3px solid #d98218;
  box-shadow: inset -3px -3px 0 #b36b12;
  transition: background-color 0.4s ease, border-color 0.4s ease;
}

.egg-shine {
  position: absolute;
  top: 16px;
  right: 18px;
  width: 8px;
  height: 16px;
  background: #ffffff;
  border-radius: 4px;
  transform: rotate(20deg);
}

.preset-controls {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  width: 100%;
}

.pixel-btn {
  background: #3a424d;
  color: var(--color-white);
  border: 3px solid var(--color-border-dark);
  box-shadow: inset 2px 2px 0 var(--color-border-light), inset -2px -2px 0 #1b1e23;
  font-family: inherit;
  font-size: 1rem;
  padding: 10px 4px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  transition: transform 0.05s ease, background-color 0.1s ease;
  outline: none;
}

.pixel-btn:hover:not(:disabled) {
  background: #475260;
}

.pixel-btn:active:not(:disabled) {
  box-shadow: inset 2px 2px 0 #1b1e23, inset -2px -2px 0 var(--color-border-light);
  transform: translate(2px, 2px);
}

.pixel-btn:focus-visible {
  outline: 3px solid var(--color-accent-gold);
  outline-offset: 2px;
}

.pixel-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.preset-btn.active {
  background: var(--color-accent-gold);
  color: #121517;
  box-shadow: inset 2px 2px 0 #ffe082, inset -2px -2px 0 #9c670a;
  font-weight: bold;
}

.btn-label {
  font-weight: bold;
}

.btn-sub {
  font-size: 0.8rem;
  opacity: 0.9;
}

.display-section {
  width: 100%;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: center;
}

.time-display {
  font-size: 3rem;
  font-weight: bold;
  letter-spacing: 4px;
  color: var(--color-white);
  text-shadow: 3px 3px 0 var(--color-border-dark);
  background: #191c20;
  padding: 8px 16px;
  border: 3px solid var(--color-border-dark);
  width: 100%;
}

.progress-container {
  width: 100%;
  height: 22px;
  background: #191c20;
  border: 3px solid var(--color-border-dark);
  position: relative;
  overflow: hidden;
}

.progress-bar {
  height: 100%;
  width: 0%;
  background-color: var(--color-accent-gold);
  box-shadow: inset 0 -3px 0 rgba(0, 0, 0, 0.3);
  transition: width 0.3s linear, background-color 0.3s ease;
}

.status-message {
  font-size: 1.25rem;
  font-weight: bold;
  color: var(--color-accent-done);
  text-shadow: 2px 2px 0 var(--color-border-dark);
  min-height: 28px;
  padding: 4px;
  animation: blink 0.9s infinite step-end;
}

@keyframes blink {
  50% {
    opacity: 0.3;
  }
}

.action-controls {
  display: flex;
  gap: 10px;
  width: 100%;
}

.action-btn {
  flex: 1;
  padding: 12px 6px;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1px;
}

@media (max-width: 380px) {
  .pixel-card {
    padding: 16px 12px;
  }
  .time-display {
    font-size: 2.4rem;
  }
  .pixel-title {
    font-size: 1.25rem;
  }
  .preset-controls {
    gap: 6px;
  }
}

document.addEventListener("DOMContentLoaded", () => {
  let totalDuration = 0;
  let remainingSeconds = 0;
  let timerId = null;
  let isRunning = false;
  let activePreset = null;

  const timeDisplay = document.getElementById("time-display");
  const progressBar = document.getElementById("progress-bar");
  const progressBarContainer = document.getElementById("progress-bar-container");
  const statusMessage = document.getElementById("status-message");
  const eggYolk = document.getElementById("egg-yolk");

  const presetButtons = document.querySelectorAll(".preset-btn");
  const btnPause = document.getElementById("btn-pause");
  const btnResume = document.getElementById("btn-resume");
  const btnReset = document.getElementById("btn-reset");

  function formatTime(seconds) {
    const safeSec = Math.max(0, Math.floor(seconds));
    const m = Math.floor(safeSec / 60);
    const s = safeSec % 60;
    return `${m}:${s < 10 ? "0" : ""}${s}`;
  }

  function updateDisplay() {
    timeDisplay.textContent = formatTime(remainingSeconds);

    let progressPercent = 0;
    if (totalDuration > 0) {
      progressPercent = Math.min(100, Math.max(0, ((totalDuration - remainingSeconds) / totalDuration) * 100));
    }

    progressBar.style.width = `${progressPercent.toFixed(1)}%`;
    progressBarContainer.setAttribute("aria-valuenow", Math.round(progressPercent));
  }

  function setPreset(seconds, presetKey) {
    clearInterval(timerId);
    timerId = null;
    isRunning = false;

    activePreset = presetKey;
    totalDuration = seconds;
    remainingSeconds = seconds;

    presetButtons.forEach(btn => {
      if (btn.getAttribute("data-time") === String(seconds)) {
        btn.classList.add("active");
      } else {
        btn.classList.remove("active");
      }
    });

    statusMessage.hidden = true;
    btnPause.disabled = false;
    btnResume.disabled = true;

    updateYolkColor(presetKey);
    updateDisplay();
    startCountdown();
  }

  function updateYolkColor(presetKey) {
    if (presetKey === "360") {
      eggYolk.style.backgroundColor = "#ffa726";
    } else if (presetKey === "480") {
      eggYolk.style.backgroundColor = "#f57c00";
    } else if (presetKey === "600") {
      eggYolk.style.backgroundColor = "#d68910";
    } else {
      eggYolk.style.backgroundColor = "var(--color-accent-gold)";
    }
  }

  function startCountdown() {
    if (timerId !== null) {
      clearInterval(timerId);
    }
    isRunning = true;
    btnPause.disabled = false;
    btnResume.disabled = true;

    timerId = setInterval(() => {
      if (remainingSeconds > 0) {
        remainingSeconds -= 1;
        updateDisplay();
        if (remainingSeconds === 0) {
          onTimerComplete();
        }
      } else {
        onTimerComplete();
      }
    }, 1000);
  }

  function onTimerComplete() {
    clearInterval(timerId);
    timerId = null;
    isRunning = false;
    remainingSeconds = 0;
    updateDisplay();

    statusMessage.hidden = false;
    btnPause.disabled = true;
    btnResume.disabled = true;
  }

  function pauseTimer() {
    if (!isRunning) return;
    clearInterval(timerId);
    timerId = null;
    isRunning = false;

    btnPause.disabled = true;
    btnResume.disabled = false;
  }

  function resumeTimer() {
    if (isRunning || remainingSeconds <= 0) return;
    startCountdown();
  }

  function resetTimer() {
    clearInterval(timerId);
    timerId = null;
    isRunning = false;
    totalDuration = 0;
    remainingSeconds = 0;
    activePreset = null;

    presetButtons.forEach(btn => btn.classList.remove("active"));
    statusMessage.hidden = true;
    btnPause.disabled = true;
    btnResume.disabled = true;

    updateYolkColor(null);
    updateDisplay();
  }

  presetButtons.forEach(btn => {
    btn.addEventListener("click", () => {
      const seconds = parseInt(btn.getAttribute("data-time"), 10);
      setPreset(seconds, btn.getAttribute("data-time"));
    });
  });

  btnPause.addEventListener("click", pauseTimer);
  btnResume.addEventListener("click", resumeTimer);
  btnReset.addEventListener("click", resetTimer);

  updateDisplay();
});
